function dadosInvalidos(err, req, res, next) {
  if (err) {
    return res
      .status(422)
      .json({ erro: 'DADOS_INVALIDOS', mensagem: 'Corpo deve ser JSON válido.' })
  }
  const rawBody = req.headers['content-length'] || req.headers['transfer-encoding']
  if (rawBody && typeof req.body !== 'object') {
    return res
      .status(422)
      .json({ erro: 'DADOS_INVALIDOS', mensagem: 'Corpo deve ser JSON válido.' })
  }
  next()
}

