      method: 'POST',
      headers: { 'X-Usuario': 'nao-existe', 'Content-Type': 'text/plain' },
      body: 'não é json'
    })
    const semJsonBody = await semJson.json()
    assert.equal(semJson.status, 422)
    assert.deepEqual(Object.keys(semJsonBody).sort(), ['erro', 'mensagem'])
  })
